package test;

import org.eclipse.swt.graphics.Image;
import org.eclipse.ui.ISharedImages;
import org.eclipse.ui.PlatformUI;
import org.eclipse.jdt.internal.ui.JavaPluginImages; // Added by the cleanup engine

public class MyImageProvider {
    public Image getErrorImage() {
        return JavaPluginImages.get(JavaPluginImages.IMG_OBJS_ERROR_ALT);
    }

    public Image getWarningImage() {
        return JavaPluginImages.get(JavaPluginImages.IMG_OBJS_WARNING_ALT);
    }

    public Image getInfoImage() {
        return JavaPluginImages.get(JavaPluginImages.IMG_OBJS_INFO_ALT);
    }
}

